#!/usr/bin/env python3
"""Figures for Lecture 2 (The Physical Body), drawn at the size of their slots.

Every number drawn here comes from calcs.py, which reads MLSysIM (the
Embodied.* machine and site, Actuators.*, and the Scenarios.* the chapter also
reads): plotted geometry uses the scenario values, and labels use the
formatted strings the slides print (deckvals val/num). Axis ranges, tick
positions, and label coordinates are layout. Plots use the kit's slideplot
helper (large type, direct labels). Colors follow the Volume IV palette: plant
slate, hazard red, latency amber, sensing teal, deterministic green; nothing
uses the accent.

Run from this folder: python3 make_figs.py   (then `make deck V=4 D=02_body`)
"""
from types import SimpleNamespace
import sys as _sys; from pathlib import Path as _Path; _sys.path.insert(0, str(_Path(__file__).resolve().parents[3] / "mlsysim"))
from mlsysim.core.units import Q_
import sys
from pathlib import Path
HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(Path(__file__).resolve().parents[3] / 'assets' / 'kit'))
sys.path.insert(0, str(HERE))
import numpy as np
import slideplot as sp
from slideplot import plt
SLATE = '#334155'
SLATE_L = '#CBD5E1'
RED = '#DC2626'
RED_L = '#FEE2E2'
AMBER = '#D97706'
AMBER_L = '#FDE7C4'
TEAL = '#0D9488'
GREEN = '#059669'
GREEN_L = '#DCFCE7'
GRAY = '#888888'
TEXT = '#1A1A2E'
COL = (5.0, 3.3)

def out(name):
    return str(HERE / f'{name}.svg')

def waterfall():
    stages = [('Exposure and readout', 11.2), ('Transport and DMA', 1.4), ('Backbone and policy', 18.5), ('Scheduling and IPC', 0.6), ('Fieldbus', 1.0), ('Current rise', 2.3)]
    colors = [TEAL, TEAL, AMBER, SLATE, SLATE, SLATE]
    backbone = 18.5
    median = 35.0
    for step in (1, 2, 3):
        fig, ax = plt.subplots(figsize=(5.8, 2.4))
        x = 0.0
        for i, ((name, v), col) in enumerate(zip(stages, colors)):
            shown = step >= 2 or name == 'Backbone and policy'
            ax.barh(1, v, left=x, color=col, height=0.5, edgecolor='white', lw=1.5, alpha=1.0 if shown else 0.0)
            x += v
        ax.barh(0, backbone, left=0, color=AMBER, height=0.5)
        ax.text(backbone + 1, 0, 'benchmark: 18.5 ms', va='center', fontsize=12, color=AMBER, fontweight='bold')
        ax.text(-1, 1, 'Capture to\ntorque onset', ha='right', va='center', fontsize=12, color=TEXT, fontweight='bold', alpha=1 if step >= 2 else 0)
        ax.text(-1, 0, 'Model only', ha='right', va='center', fontsize=12, color=TEXT, fontweight='bold')
        ax.text(median, 1.45, 'median 35', ha='center', va='bottom', fontsize=11.5, color=SLATE, fontweight='bold', alpha=1 if step >= 2 else 0)
        ax.text(stages[0][1] / 2, 1.45, 'exposure,\nreadout', ha='center', va='bottom', fontsize=11, color=TEAL, alpha=1 if step >= 2 else 0)
        a3 = 1 if step >= 3 else 0
        ax.axvline(60.0, color=GREEN, lw=2, ls='--', alpha=a3)
        ax.text(60.0 - 0.8, -0.55, 'deadline 60 ms', color=GREEN, fontsize=11, fontweight='bold', ha='right', alpha=a3)
        ax.plot([46.2], [1], marker='|', ms=26, mew=2.5, color=SLATE, alpha=a3)
        ax.text(46.2, 0.72, 'p99 46.2', ha='center', va='top', fontsize=11, color=SLATE, alpha=a3)
        ax.plot([68.4], [1], marker='|', ms=26, mew=2.5, color=RED, alpha=a3)
        ax.text(68.4, 0.72, 'p99.9 68.4', ha='center', va='top', fontsize=11, color=RED, fontweight='bold', alpha=a3)
        ax.set_xlim(0, 75)
        ax.set_ylim(-0.75, 2.2)
        ax.set_yticks([])
        ax.spines['left'].set_visible(False)
        ax.set_xlabel('Age of the observation (ms)')
        sp.save(fig, out(f'waterfall_step{step}'))

def mug_travel():
    rows = [('Median\n35 ms', 7.0, SLATE, '7 mm'), ('p99.9\n68.4 ms', 13.68, RED, '13.7 mm')]
    for step in (1, 2):
        fig, ax = plt.subplots(figsize=(3.7, 1.9))
        for i, (lab, v, col, txt) in enumerate(rows):
            y = 1 - i
            al = 1.0 if i < step else 0.0
            ax.barh(y, v, color=col, height=0.6, alpha=al)
            ax.text(v + 0.3, y, txt, va='center', fontsize=12, fontweight='bold', color=col, alpha=al)
            ax.text(-0.4, y, lab, ha='right', va='center', fontsize=12, fontweight='bold', color=TEXT)
        ax.axvline(12.0, color=GREEN, lw=2, ls='--')
        ax.text(12.0, 1.55, 'allowed 12 mm', color=GREEN, fontsize=11.5, fontweight='bold', ha='center')
        ax.set_xlim(0, 17)
        ax.set_ylim(-0.5, 1.8)
        ax.set_yticks([])
        ax.spines['left'].set_visible(False)
        ax.set_xlabel('Mug travel (mm)', fontsize=12)
        sp.save(fig, out(f'mug_travel_step{step}'))

